418	// ====== 状态管理器 ======
419	class GameStateManager {
420	  constructor() {
421	    this._state = null;
422	    this._dirtyFlags = new Set();
423	    this._listeners = [];
424	  }
425	
426	  /** 初始化新游戏 */
427	  newGame() {
428	    this._state = createDefaultState();
429	    this._markAllDirty();
430	    this._notify();
431	    return this._state;
432	  }
433	
434	  /** 获取当前完整状态（只读引用，请勿直接修改嵌套对象） */
435	  getState() {
436	    if (!this._state) {
437	      throw new Error(
438	        "GameState not initialized. Call newGame() or loadGame() first.",
439	      );
440	    }
441	    return this._state;
442	  }
443	
444	  /** 获取状态某个路径的值 */
445	  get(path) {
446	    const parts = path.split(".");
447	    let val = this.getState();
448	    for (const p of parts) {
449	      if (val == null) return undefined;
450	      val = val[p];
451	    }
452	    return val;
453	  }
454	
455	  /**
456	   * 更新状态某个路径的值
457	   * 用法: update('player.age', 25) 或 update('player', { age: 25, ... })
458	   */
459	  update(path, value) {
460	    const parts = path.split(".");
461	    const state = this.getState();
462	
463	    // 导航到父对象
464	    let parent = state;
465	    for (let i = 0; i < parts.length - 1; i++) {
466	      parent = parent[parts[i]];
467	    }
468	
469	    const key = parts[parts.length - 1];
470	    parent[key] = value;
471	
472	    // 标记脏路径
473	    this._dirtyFlags.add(path);
474	    this._notify();
475	  }
476	
477	  /** 批量更新（用于一次性修改多个字段） */
478	  batchUpdate(updates) {
479	    for (const [path, value] of Object.entries(updates)) {
480	      const parts = path.split(".");
481	      const state = this.getState();
482	      let parent = state;
483	      for (let i = 0; i < parts.length - 1; i++) {
484	        parent = parent[parts[i]];
485	      }
486	      parent[parts[parts.length - 1]] = value;
487	      this._dirtyFlags.add(path);
488	    }
489	    this._notify();
490	  }
491	
492	  /** 添加消息到日志 */
493	  addMessage(text, type = "info") {
494	    const state = this.getState();
495	    state.messageLog.push({
496	      day: state.player.day,
497	      text,
498	      type, // 'info'|'success'|'danger'|'event'|'warning'
499	    });
500	    // 限制日志长度
501	    if (state.messageLog.length > 500) {
502	      state.messageLog = state.messageLog.slice(-300);
503	    }
504	    this._dirtyFlags.add("messageLog");
505	    this._notify();
506	  }
507	
508	  /** 导入存档 */
509	  importState(savedState) {
510	    this._state = savedState;
511	    this._state.lastPlayedAt = Date.now();
512	    // === v1.0 → v1.1 迁移：fame 从 status 移到 player + 新增疾病/习惯容器 ===
513	    var s = this._state;
514	    if (s.status && typeof s.status.fame === "number") {
515	      if (s.player) s.player.fame = s.status.fame;
516	      delete s.status.fame;
517	    }
518	    if (s.player && typeof s.player.fame !== "number") {
519	      s.player.fame = 0;
520	    }
521	    if (s.status && !s.status.illnesses) s.status.illnesses = [];
522	    if (s.flags && !s.flags._habits) {
523	      s.flags._habits = {
524	        junkFoodMeals: 0,
525	        lowHungerStreak: 0,
526	        lowHygieneStreak: 0,
527	        lowHappinessStreak: 0,
528	        highFatigueStreak: 0,
529	        lateNightActions: 0,
530	        stomach_inflammationCount: 0,
531	      };
532	    }
533	    if (s.flags && !s.flags._deferred) s.flags._deferred = {};
534	    if (s.flags && !s.flags._amenityHabitCount) s.flags._amenityHabitCount = {};
535	    // v1.1 → v1.2 迁移：skillBranches + talentNodes
536	    if (!s.skillBranches) s.skillBranches = {};
537	    if (!s.talentNodes) s.talentNodes = {};
538	    // v1.2 → v1.3 迁移：企业命运 ceasedExistence
539	    if (s.enterpriseFate && s.enterpriseFate.companies) {
540	      for (var _cid in s.enterpriseFate.companies) {
541	        var _co = s.enterpriseFate.companies[_cid];
542	        if (_co && typeof _co.ceasedExistence === "undefined") {
543	          _co.ceasedExistence = false;
544	          _co.ceasedAt = null;
545	        }
546	      }
547	    }
548	    // v1.3 → v1.4 迁移：企业命运 Phase 1 新字段
549	    if (s.enterpriseFate) {
550	      if (!s.enterpriseFate.mergedCompaniesMap)
551	        s.enterpriseFate.mergedCompaniesMap = {};
552	      if (!s.enterpriseFate.industryIndex) s.enterpriseFate.industryIndex = {};
553	      if (!s.enterpriseFate.quarterlyReports)
554	        s.enterpriseFate.quarterlyReports = [];
555	      // 为每家公司添加新字段（兼容旧存档）
556	      for (var _cid2 in s.enterpriseFate.companies) {
557	        var _co2 = s.enterpriseFate.companies[_cid2];
558	        if (_co2) {
559	          if (typeof _co2.ipoed === "undefined") _co2.ipoed = false;
560	          if (typeof _co2.ipoDay === "undefined") _co2.ipoDay = null;
561	          if (typeof _co2.absorbedBy === "undefined") _co2.absorbedBy = null;
562	          if (typeof _co2.absorbedName === "undefined")
563	            _co2.absorbedName = null;
564	        }
565	      }
566	    }
567	    // v1.4 → v1.5 迁移：创业系统 + 内幕交易系统
568	    if (!s.startup) {
569	      s.startup = {
570	        status: "none",
571	        company: null,
572	        flags: {
573	          registered: false,
574	          firstProductLaunched: false,
575	          hasInvestors: false,
576	          ipoFiled: false,
577	          exited: false,
578	          exitType: null,
579	          exitDay: null,
580	          exitValue: 0,
581	        },
582	        history: {
583	          foundedDay: null,
584	          exitedDay: null,
585	          exitType: null,
586	          exitValue: 0,
587	          peakValuation: 0,
588	          totalRevenue: 0,
589	          employeesHired: 0,
590	        },
591	      };
592	    }
593	    if (!s.insiderTrading) {
594	      s.insiderTrading = {
595	        activeRumor: null,
596	        rumorHistory: [],
597	        tradeLog: [],
598	        audits: [],
599	        currentPenalty: {
600	          tradingBanned: false,
601	          tradingBanEndDay: 0,
602	          fine: 0,
603	          reputationDamage: 0,
604	        },
605	      };
606	    }
607	    // enterpriseFate pendingEvents 字段
608	    if (s.enterpriseFate && !s.enterpriseFate.pendingEvents) {
609	      s.enterpriseFate.pendingEvents = [];
610	    }
611	    // v1.5 → v1.6 迁移：链式事件队列
612	    if (s.flags && !s.flags._chainEventQueue) {
613	      s.flags._chainEventQueue = [];
614	    }
615	    // v1.5 → v1.6 迁移：世界参数反馈环
616	    if (!s._worldParams) {
617	      if (typeof createDefaultWorldParams === "function") {
618	        s._worldParams = createDefaultWorldParams();
619	      } else {
620	        s._worldParams = null;
621	      }
622	    }
623	    // 版本升级标记
624	    if (!s.version) s.version = "1.0.0";
625	    s.version = "1.6.0";
626	    this._markAllDirty();
627	    this._notify();
628	  }
629	
630	  /** 检查路径是否脏（自上次 cleanDirty 后） */
631	  isDirty(path) {
632	    return this._dirtyFlags.has(path);
633	  }
634	
635	  /** 清除所有脏标记（渲染后调用） */
636	  cleanAllDirty() {
637	    this._dirtyFlags.clear();
638	  }
639	
640	  /** 订阅状态变更 */
641	  onChange(callback) {
642	    this._listeners.push(callback);
643	  }
644	
645	  // ====== 内部方法 ======
646	  _markAllDirty() {
647	    this._dirtyFlags.add("*");
648	  }
649	
650	  _notify() {
651	    for (const cb of this._listeners) {
652	      try {
653	        cb(this._state);
654	      } catch (e) {
655	        /* 静默 */
656	      }
657	    }
658	  }
659	}
660	
661	// ====== 单例导出 ======
662	const StateManager = new GameStateManager();
663	
664	// 使其在全局可访问（方便调试）
665	if (typeof window !== "undefined") {
666	  window.StateManager = StateManager;
667	}
668	
669	/**
670	 * 添加一条当日收支记录
671	 * @param {object} state - 游戏状态
672	 * @param {"income"|"expense"} type - 收入或支出
673	 * @param {string} category - 分类键（如 "job_income", "rent", "food"）
674	 * @param {number} amount - 金额（正数）
675	 * @param {string} description - 描述文本
676	 */
677	function addDailyTransaction(state, type, category, amount, description) {
678	  if (!state.flags._dailyTransactions) {
679	    state.flags._dailyTransactions = [];
680	  }
681	  state.flags._dailyTransactions.push({
682	    type: type,
683	    category: category,
684	    amount: Math.round(amount),
685	    description: description,
686	  });
687	}
