function init() {
  // 检查是否有存档
  if (hasSave()) {
    // 显示欢迎界面
  }

  // 注册状态变更回调
  StateManager.onChange(() => {
    if (gameStarted) {
      // 函数节流：每 100ms 最多渲染一次
      if (!init._renderTimeout) {
        init._renderTimeout = setTimeout(() => {
          renderAll();
          init._renderTimeout = null;
        }, 100);
      }
    }
  });

  // 显示欢迎界面
  showWelcome();

  // 全局点击事件委托（Tab 切换）
  document.getElementById("tab-bar").addEventListener("click", (e) => {
    const btn = e.target.closest(".tab-btn");
    if (btn && btn.dataset.tab) {
      switchTab(btn.dataset.tab);
    }
  });

  // 存档按钮
  // 帮助按钮
  document.getElementById("btn-help").addEventListener("click", () => {
    showHelpModal();
  });

  // 存档按钮
  document.getElementById("btn-save").addEventListener("click", () => {
    if (gameStarted) showSaveMenu();
  });

  // 读档按钮
  document.getElementById("btn-load").addEventListener("click", () => {
    showLoadMenu();
  });

  // 新游戏按钮（Header）
  document
    .getElementById("btn-new-game-header")
    .addEventListener("click", () => {
      if (gameStarted) {
        showModal({
          title: "开始新游戏？",
          body: "<p>当前进度将会丢失。建议先存档。</p>",
          buttons: [
            { text: "取消", cls: "", callback: () => {} },
            {
              text: "确认新游戏",
              cls: "btn-danger",
              callback: () => showWelcome(),
            },
          ],
        });
      }
    });

  // 移动端菜单按钮
  document.getElementById("mobile-menu-btn").addEventListener("click", () => {
    document.getElementById("sidebar").classList.toggle("open");
  });

  console.log("🏙️ 城市浮生记 initialized.");
}

